/**
 * @title ReversibleVault
 * @notice Stores assets and handles "Time-Travel" reversibility.
 * @dev Implements the "System Boundaries" rubric: Logic and Funds are separate.
 */
contract ReversibleVault is Ownable, ReentrancyGuard, Pausable {

    // --- State Variables ---
    IERC20 public immutable asset; // The underlying token (e.g., USDC)
    address public settlementEngine; // The only contract allowed to move funds

    // "Ghost Tokens": Internal accounting of who owns what
    mapping(address => uint256) public internalBalance;
    
    // "Locked Funds": Funds currently subject to a dispute window
    mapping(address => uint256) public lockedBalance;

    // --- Events ---
    event Deposit(address indexed user, uint256 amount);
    event WithdrawalRequested(address indexed user, uint256 amount);
    event WithdrawalFinalized(address indexed user, uint256 amount);
    event StateReverted(address indexed criminal, address indexed victim, uint256 amount);

    // --- Modifiers ---
    modifier onlyEngine() {
        require(msg.sender == settlementEngine, "Caller is not the Settlement Engine");
        _;
    }

    // FIX: Pass msg.sender to Ownable
    constructor(address _asset) Ownable(msg.sender) {
        asset = IERC20(_asset);
    }

    // --- Configuration ---
    function setSettlementEngine(address _engine) external onlyOwner {
        settlementEngine = _engine;
    }

    // --- 1. The Entry Point (Inflow) ---
    /**
     * @notice Users deposit Real Assets to get "Ghost Tokens".
     */
    function deposit(uint256 amount) external nonReentrant whenNotPaused {
        require(amount > 0, "Amount must be > 0");
        
        // Transfer physical tokens to this vault
        bool success = asset.transferFrom(msg.sender, address(this), amount);
        require(success, "Transfer failed");

        // Mint internal "Ghost Tokens"
        internalBalance[msg.sender] += amount;
        emit Deposit(msg.sender, amount);
    }

    // --- 2. The Core Logic (Engine Only) ---
    /**
     * @notice The Settlement Engine moves Ghost Tokens during a batch match.
     * @dev Does NOT move physical tokens, only updates internal ledgers.
     */
    function internalTransfer(address from, address to, uint256 amount) external onlyEngine {
        require(internalBalance[from] >= amount, "Insufficient internal balance");
        
        internalBalance[from] -= amount;
        internalBalance[to] += amount;
        
        // Lock the recipient's funds for the challenge period (Partial Finality)
        lockedBalance[to] += amount; 
    }

    /**
     * @notice The "Eraser". Called if a Batch is successfully disputed.
     * @dev Reverses a specific transfer.
     */
    function revertState(address criminal, address victim, uint256 amount) external onlyEngine {
        // Slash the criminal's ghost tokens
        // In a real scenario, we might burn them, but here we return to victim
        // Check if criminal has enough (if they traded away, we would trace taint, but simplified here)
        uint256 slashAmount = amount;
        if (internalBalance[criminal] < amount) {
             slashAmount = internalBalance[criminal]; // Take what they have
        }

        internalBalance[criminal] -= slashAmount;
        if (lockedBalance[criminal] >= slashAmount) {
            lockedBalance[criminal] -= slashAmount; 
        }
        
        internalBalance[victim] += slashAmount;
        
        emit StateReverted(criminal, victim, slashAmount);
    }

    /**
     * @notice Releases locks after the batch is Finalized.
     */
    function unlockFunds(address user, uint256 amount) external onlyEngine {
        // Safe subtraction
        if (lockedBalance[user] >= amount) {
            lockedBalance[user] -= amount;
        } else {
            lockedBalance[user] = 0;
        }
    }

    // --- 3. The Exit Point (Outflow) ---
    /**
     * @notice Users withdraw Real Assets. 
     * @dev Checks "Solvency" invariant: Cannot withdraw locked funds.
     */
    function withdraw(uint256 amount) external nonReentrant whenNotPaused {
        uint256 available = internalBalance[msg.sender] - lockedBalance[msg.sender];
        require(amount <= available, "Funds are currently locked in a pending batch");

        internalBalance[msg.sender] -= amount;
        
        bool success = asset.transfer(msg.sender, amount);
        require(success, "Transfer failed");

        emit WithdrawalFinalized(msg.sender, amount);
    }

    // --- 4. Emergency Controls (Circuit Breaker) ---
    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}
